import {DEFAULT_ODD_LIMIT,scale,mod,classifyTargets,createTargetClassifier,targets} from './engine.mjs';
export function chordShape(s,degrees){const notes=scale(s).notes,ks=degrees.map(i=>notes[i].k).sort((a,b)=>a-b);return ks.map(k=>k-ks[0]);}
export function chordOccurrences(s,degrees){if(!degrees.length)return [];const notes=scale(s).notes,shape=chordShape(s,degrees),byK=new Map(notes.map((n,i)=>[n.k,i]));return notes.flatMap(n=>{const ds=shape.map(k=>byK.get(n.k+k));return ds.every(i=>i!==undefined)?[ds.sort((a,b)=>a-b)]:[];});}
export function chordPair(s,i,j,ts,tol,classify=v=>classifyTargets(s,v,ts,tol)){const ns=scale(s).notes,c=mod(ns[j].c-ns[i].c,s.p),k=ns[j].k-ns[i].k;const match=classify({c,k});return {c,k,q:Math.round((c-k*s.g)/s.p),...match};}
export function bestChordTarget(pair,other){const eligible=other?[...pair.mapped,...pair.hits]:pair.mapped;return eligible.filter(t=>t.within).sort((a,b)=>Math.abs(a.error)-Math.abs(b.error)||Number(b.identity)-Number(a.identity))[0]||null;}
export function analyzeChord(s,degrees,limit=DEFAULT_ODD_LIMIT,tol=10,other=true,primeLimit=null){const ds=[...new Set(degrees)].sort((a,b)=>a-b),ts=targets(limit,primeLimit),pairs=[];for(let i=0;i<ds.length;i++)for(let j=i+1;j<ds.length;j++){const pair=chordPair(s,ds[i],ds[j],ts,tol);pairs.push({i:ds[i],j:ds[j],...pair,best:bestChordTarget(pair,other)});}const errors=pairs.filter(p=>p.best).map(p=>Math.abs(p.best.error));return {pairs,qualified:pairs.length>0&&errors.length===pairs.length,max:errors.length?Math.max(...errors):null,covered:errors.length,total:pairs.length};}
const searchCache=new Map();
export function discoverChords(s,size=3,limit=DEFAULT_ODD_LIMIT,tol=10,other=true,primeLimit=null){
 const key=JSON.stringify([s.basis,s.rows,s.p,s.g,s.n,s.mode,size,limit,primeLimit,tol,other]);if(searchCache.has(key))return searchCache.get(key);
 if(s.n>96)throw Error('Automatic chord discovery supports up to 96 notes. Choose a smaller scale to search, or select chords manually in the HexBoard workspace.');
 if(![3,4].includes(size))throw Error('Choose triads or tetrads.');if(scale(s).collision)return {groups:[],count:0,collision:true};
 const notes=scale(s).notes,ts=targets(limit,primeLimit),classify=createTargetClassifier(s,ts,tol),pair=Array.from({length:s.n},()=>[]);for(let i=0;i<s.n;i++)for(let j=i+1;j<s.n;j++)pair[i][j]=bestChordTarget(chordPair(s,i,j,ts,tol,classify),other);
 const groups=new Map();let count=0;
 function visit(ds,start){if(ds.length===size){count++;const labels=[],errors=[];let mapped=0;for(let a=0;a<size;a++)for(let b=a+1;b<size;b++){const t=pair[ds[a]][ds[b]];labels.push(t.label);errors.push(Math.abs(t.error));if(t.identity)mapped++;}const score=Math.max(...errors),rms=Math.sqrt(errors.reduce((a,v)=>a+v*v,0)/errors.length),ks=ds.map(i=>notes[i].k).sort((a,b)=>a-b),shape=ks.map(k=>k-ks[0]),key=shape.join(',');let group=groups.get(key);const item={degrees:[...ds],max:score,rms,mapped,total:errors.length,labels};if(!group){group={shape,occurrences:[],best:item};groups.set(key,group);}group.occurrences.push(item);if(score<group.best.max-1e-8||Math.abs(score-group.best.max)<1e-8&&rms<group.best.rms)group.best=item;return;}for(let j=start;j<=s.n-(size-ds.length);j++)if(ds.every(i=>pair[i][j]))visit([...ds,j],j+1);}
 visit([],0);const result={groups:[...groups.values()].sort((a,b)=>a.best.max-b.best.max||a.best.rms-b.best.rms||a.shape.at(-1)-b.shape.at(-1)),count,collision:false};if(searchCache.size>5)searchCache.clear();searchCache.set(key,result);return result;
}
